// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.feedback.RuntimeFeedbackDescriptor.RetainedMemoryAccount;
import org.junit.jupiter.api.Test;

/** Cache applicability is full equality, and every retained detached-key owner has a bounded lifetime. */
class PackedProviderCacheIdentityTest {
	private record Identity(Object owner, String value) implements PackedProviderCacheIdentity {
		@Override
		public int hashCode() {
			return 7;
		} // Deliberate routing collision, never equality authority.

		@Override
		public boolean accountRetainedMemory(RetainedMemoryAccount account) {
			if (account.add(this, 32L)) {
				account.add(owner, 16L);
				account.add(value, 40L + 2L * value.length());
			}
			return true;
		}
	}

	@Test
	void sameHashesCannotCrossFullProviderEqualityOrTheAbsentNamespace() {
		Object owner = new Object();
		var first = context(new Identity(owner, "explicit"));
		var equal = context(new Identity(owner, "explicit"));
		var different = context(new Identity(owner, "inferred"));
		assertThat(first).isEqualTo(equal).isNotEqualTo(different).isNotEqualTo(context(null));
		assertThat(first.structurallyMatches(equal)).isTrue();
		assertThat(first.structurallyMatches(different)).isFalse();
		assertThat(first.structurallyMatches(context(new Identity(new Object(), "explicit")))).isFalse();
	}

	@Test
	void sharedNodesAreChargedOnceAndEveryRootReferenceIsReleased() {
		Object owner = new Object();
		String payload = new String("same detached lexical payload");
		Identity first = new Identity(owner, payload);
		Identity second = new Identity(owner, payload);
		PackedProviderIdentityBudget budget = new PackedProviderIdentityBudget(4096L);
		assertThat(budget.tryRetain(first)).isTrue();
		long one = budget.bytes();
		assertThat(budget.tryRetain(first)).isTrue();
		assertThat(budget.bytes()).isEqualTo(one);
		assertThat(budget.tryRetain(second)).isTrue();
		assertThat(budget.bytes()).isGreaterThan(one).isLessThan(2L * one);
		budget.release(first);
		assertThat(budget.bytes()).isGreaterThan(one);
		budget.release(first);
		assertThat(budget.bytes()).isEqualTo(one);
		budget.release(second);
		assertThat(budget.bytes()).isZero();
	}

	@Test
	void unaccountableAndSaturatedKeysCannotEnterTheCacheAsAbsent() {
		StatementPattern source = new StatementPattern(new Var("s"), new Var("p"), new Var("o"));
		PackedPlanCache cache = new PackedPlanCache(2, 1, 0L);
		var fingerprint = cache.fingerprint(source);
		assertThat(cache.beginFlight(fingerprint, context(new Identity(new Object(), "explicit")), source)).isNull();
		var legacy = cache.beginFlight(fingerprint, context(null), source);
		assertThat(legacy.owner()).isTrue();
		cache.fail(legacy, new IllegalStateException("test owner retired"));
		PackedProviderIdentityBudget budget = new PackedProviderIdentityBudget(Long.MAX_VALUE);
		PackedProviderCacheIdentity saturated = account -> {
			account.add(new Object(), Long.MAX_VALUE);
			return true;
		};
		assertThat(budget.tryRetain(saturated)).isFalse();
		assertThat(budget.tryRetain(account -> false)).isFalse();
		assertThat(budget.bytes()).isZero();
	}

	@Test
	void matchingFlightsCoalesceButDifferentReadOwnersNeverDo() {
		StatementPattern source = new StatementPattern(new Var("s"), new Var("p"), new Var("o"));
		PackedPlanCache cache = new PackedPlanCache(2, 1, 16384L);
		var fingerprint = cache.fingerprint(source);
		Object owner = new Object();
		var first = cache.beginFlight(fingerprint, context(new Identity(owner, "explicit")), source);
		var same = cache.beginFlight(fingerprint, context(new Identity(owner, "explicit")), source);
		var distinct = cache.beginFlight(fingerprint, context(new Identity(owner, "inferred")), source);
		assertThat(first.owner()).isTrue();
		assertThat(same.owner()).isFalse();
		assertThat(distinct.owner()).isTrue();
		cache.fail(first, new IllegalStateException("first owner retired"));
		assertThat(same.await()).isNull();
		cache.fail(distinct, new IllegalStateException("distinct owner retired"));
	}

	private static PackedPlanCache.Context context(PackedProviderCacheIdentity identity) {
		return new PackedPlanCache.Context(1L, 2L, 3L, 4L, 5L, 6L, 7L, 8L, 9L, 10L, identity);
	}
}
